<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';wajib_role(['ADMIN']);$id=get_id();$st=mysqli_prepare($koneksi,"SELECT * FROM program_studi WHERE id_program_studi=?");mysqli_stmt_bind_param($st,'i',$id);mysqli_stmt_execute($st);$d=mysqli_fetch_assoc(mysqli_stmt_get_result($st));mysqli_stmt_close($st);if(!$d)die('Data tidak ditemukan.');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$old=$d;$d['kode_program_studi']=trim($_POST['kode_program_studi']??'');$d['nama_program_studi']=trim($_POST['nama_program_studi']??'');$d['id_fakultas']=(int)$_POST['id_fakultas'];$d['jenjang']=trim($_POST['jenjang']??'S1');$d['status_aktif']=trim($_POST['status_aktif']??'Aktif');if(!$d['kode_program_studi']||!$d['nama_program_studi']||!$d['id_fakultas'])$error='Data wajib diisi.';if(!$error){$st=mysqli_prepare($koneksi,"UPDATE program_studi SET id_fakultas=?,kode_program_studi=?,nama_program_studi=?,jenjang=?,status_aktif=? WHERE id_program_studi=?");mysqli_stmt_bind_param($st,'issssi',$d['id_fakultas'],$d['kode_program_studi'],$d['nama_program_studi'],$d['jenjang'],$d['status_aktif'],$id);if(mysqli_stmt_execute($st)){audit_log($koneksi,(int)$_SESSION['id_pengguna'],'program_studi',(string)$id,'UPDATE',$old,$d);flash('success','Program Studi berhasil diperbarui.');redirect_to('prodi.php');}$error='Gagal memperbarui.';mysqli_stmt_close($st);}}$f=mysqli_query($koneksi,"SELECT id_fakultas,nama_fakultas FROM fakultas ORDER BY nama_fakultas");?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Program Studi</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading"><span class="eyebrow">MASTER DATA</span><h1>Edit Program Studi</h1></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="dashboard-panel form-panel"><form method="post"><div class="form-grid"><div class="form-group"><label>Kode</label><input name="kode_program_studi" required value="<?=e($d['kode_program_studi'])?>"></div><div class="form-group"><label>Nama</label><input name="nama_program_studi" required value="<?=e($d['nama_program_studi'])?>"></div><div class="form-group"><label>Fakultas</label><select name="id_fakultas"><?php while($x=mysqli_fetch_assoc($f)):?><option value="<?=$x['id_fakultas']?>" <?=$d['id_fakultas']==$x['id_fakultas']?'selected':''?>><?=e($x['nama_fakultas'])?></option><?php endwhile;?></select></div><div class="form-group"><label>Jenjang</label><select name="jenjang"><?php foreach(['D3','D4','S1','S2','S3'] as $x):?><option <?=$d['jenjang']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="form-group"><label>Status</label><select name="status_aktif"><option <?=$d['status_aktif']==='Aktif'?'selected':''?>>Aktif</option><option <?=$d['status_aktif']==='Tidak Aktif'?'selected':''?>>Tidak Aktif</option></select></div></div><div class="form-actions"><a class="btn btn-outline" href="prodi.php">Batal</a><button class="btn btn-primary">Simpan Perubahan</button></div><?=csrf_field()?></form></div></main><script src="script.js"></script></body></html>